 end=min(N,begin+4096);ids=tri[faces[begin:end]];a,b,c=p[ids[:,0]],p[ids[:,1]],p[ids[:,2]];bb,q=closest_barycentric_closed(originalPoints[begin:end],a,b,c);minBary=min(minBary,float(bb.min()));checkpointPointMaxError=max(checkpointPointMaxError,float(np.linalg.norm(q-points[begin:end],axis=1).max()));exactRestMax=max(exactRestMax,float(np.linalg.norm(q-originalPoints[begin:end],axis=1).max()));reconstructed=np.einsum('ni,nij->nj',bb,p[ids]);maxReconstruction=max(maxReconstruction,float(np.linalg.norm(reconstructed-q,axis=1).max()));values=np.einsum('ni,nij->nj',bb,dw[ids]);values/=values.sum(1)[:,None];stored=values.astype(np.float32);assert np.array_equal(values>0,stored>0),'Positive Float32 underflow';rows,cols=np.nonzero(stored);counts[begin:end]=np.count_nonzero(stored,axis=1);chunksI.append(cols.astype(np.uint8));chunksW.append(stored[rows,cols]);minStored=min(minStored,float(stored[stored>0].min()));maxWeightSum=max(maxWeightSum,float(abs(stored.sum(1,dtype=float)-1).max()))
